    void tagPage(LinearLayout body){webFields=tagCard(body,false);comfyFields=tagCard(body,true);if(webInfo!=null)populateTags(webFields,webInfo,false);if(comfyInfo!=null)populateTags(comfyFields,comfyInfo,true);LinearLayout export=card(body,t("导出参数","Export parameters"));buttons(export,button(t("一键导出 TXT","Export TXT"),()->{Metadata.Result web=webInfo,comfy=comfyInfo;task(j->{ArrayList<File> files=new ArrayList<>();if(web!=null&&!web.web.isEmpty())files.add(txt("WebUI.txt",format(web.web)));if(comfy!=null&&!comfy.comfy.isEmpty()){StringBuilder text=new StringBuilder();for(Map<String,String> fields:comfy.comfy)text.append(format(fields)).append('\n');files.add(txt("ComfyUI.txt",text.toString()));}return files;},files->saveOutputs(files,FOLDERS[6]));}));export.addView(label(t("WebUI 与 ComfyUI 分别导出；未载入或没有信息的不导出。","Exports WebUI and ComfyUI separately; empty or unloaded panels are skipped."),12,false));}
    LinearLayout tagCard(LinearLayout body,boolean comfy){LinearLayout c=card(body,comfy?"ComfyUI":"WebUI");LinearLayout fields=column();buttons(c,button(t("选择图片并读取","Open image and read"),()->pick("image/*",false,files->{if(files.isEmpty())return;File f=files.get(0);task(j->{Metadata.Result result=Metadata.inspect(f,j);ui.post(()->{if(destroyed)return;if(comfy)comfyInfo=result;else webInfo=result;populateTags(fields,result,comfy);});return Collections.emptyList();},null);})));c.addView(fields);fields.addView(label(t("尚未读取图片","No image loaded"),13,false));return fields;}
    void populateTags(LinearLayout body,Metadata.Result r,boolean comfy){body.removeAllViews();if(comfy){if(r.comfy.isEmpty()){body.addView(label(t("未发现 ComfyUI 信息","No ComfyUI information"),13,false));}else{LinearLayout fields=column();String[] samplers=new String[r.comfy.size()];for(int i=0;i<samplers.length;i++)samplers[i]=r.comfy.get(i).containsKey("采样节点 / Sampler node")?r.comfy.get(i).get("采样节点 / Sampler node"):t("原始 JSON","Raw JSON");Spinner selected=spinner(body,t("选择采样节点","Select sampler"),samplers,0,i->{fields.removeAllViews();tagFields(fields,new ArrayList<>(r.comfy.get(i).entrySet()),0);});body.addView(fields);tagFields(fields,new ArrayList<>(r.comfy.get(0).entrySet()),0);}if(!r.note.isEmpty())body.addView(label(r.note,12,false));}else{if(r.web.isEmpty())body.addView(label(t("未发现 WebUI 信息","No WebUI information"),13,false));else tagFields(body,new ArrayList<>(r.web.entrySet()),0);}}
    void tagFields(LinearLayout body,List<Map.Entry<String,String>> fields,int start){int end=Math.min(fields.size(),start+40);for(int i=start;i<end;i++){Map.Entry<String,String> f=fields.get(i);tagField(body,f.getKey(),f.getValue());}if(end<fields.size()){Button more=button(t("显示更多参数","Show more parameters"),()->{});more.setOnClickListener(v->{body.removeView(more);tagFields(body,fields,end);});body.addView(more,new LinearLayout.LayoutParams(-1,dp(48)));}}
    void tagField(LinearLayout body,String key,String value){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView caption=label(key,14,true);row.addView(caption,new LinearLayout.LayoutParams(0,-2,1));Button copy=button("⧉",()->{android.content.ClipboardManager cb=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);try{cb.setPrimaryClip(ClipData.newPlainText(key,value));toast(t("已复制","Copied"));}catch(RuntimeException ex){toast(t("文本过大，请导出 TXT","Text too large for clipboard; export TXT"));}});copy.setContentDescription(t("复制 ","Copy ")+key);row.addView(copy,new LinearLayout.LayoutParams(dp(48),dp(48)));body.addView(row);EditText text=new EditText(this);text.setText(value.length()>8192?value.substring(0,8192)+t("\n预览已缩短，复制或 TXT 导出保留完整内容","\nPreview shortened; Copy and TXT preserve the full content"):value);text.setTextSize(13);text.setKeyListener(null);text.setTextIsSelectable(true);text.setMinLines(2);text.setMaxLines(9);text.setHorizontallyScrolling(false);text.setVerticalScrollBarEnabled(true);text.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN)v.getParent().requestDisallowInterceptTouchEvent(true);if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)v.getParent().requestDisallowInterceptTouchEvent(false);return false;});body.addView(text,new LinearLayout.LayoutParams(-1,-2));}
    String format(Map<String,String> fields){StringBuilder b=new StringBuilder();for(Map.Entry<String,String> e:fields.entrySet())b.append(e.getKey()).append(":\n").append(e.getValue()).append("\n\n");return b.toString();}File txt(String name,String content)throws Exception{File out=Files.unique(outputDir,name);try(OutputStream o=new FileOutputStream(out)){o.write(content.getBytes(Files.UTF8));}return out;}
    int colorIndex(){int color=prefs.getInt("color",Color.WHITE);return color==Color.BLACK?1:color==0xffeee9f7?2:color==0xfff8e4ee?3:0;}
