    public void onBackPressed(){if(overlay!=null)closeDrawer();else if(busy)new AlertDialog.Builder(this).setMessage(t("取消当前任务？","Cancel current task?")).setPositiveButton(t("取消任务","Cancel task"),(d,w)->{if(active!=null)active.cancelled=true;}).setNegativeButton(t("继续处理","Keep processing"),null).show();else super.onBackPressed();}
